import { useId, type ReactNode } from 'react';
import { Accordion, AccordionItem, AccordionPanel, AccordionTrigger, cn } from '@gntik-ai/ui';
import { sampleFaqs } from './fixtures';

export interface FaqItem {
  id: string;
  question: string;
  answer: ReactNode;
}

export interface FaqProps {
  items?: FaqItem[];
  title?: ReactNode;
  description?: ReactNode;
  /** `stacked` (heading over the list) or `split` (heading left from `lg`). */
  layout?: 'stacked' | 'split';
  /** Ids of the items open on mount. */
  defaultOpen?: string[];
  /** Allow several items open at once. */
  multiple?: boolean;
  headingLevel?: 'h2' | 'h3';
  className?: string;
}

/** Frequently asked questions in an accordion, with a heading block. */
export function Faq({
  items = sampleFaqs,
  title = 'Frequently asked questions',
  description = 'Can’t find what you’re looking for? Reach out to our support team.',
  layout = 'stacked',
  defaultOpen,
  multiple = false,
  headingLevel: Heading = 'h2',
  className,
}: FaqProps) {
  const titleId = useId();
  const split = layout === 'split';
  return (
    <section
      aria-labelledby={titleId}
      className={cn('px-4 py-16 sm:px-6 sm:py-20', split ? 'mx-auto grid max-w-6xl gap-10 lg:grid-cols-[1fr_2fr]' : 'mx-auto max-w-3xl', className)}
    >
      <div className={cn(!split && 'text-center')}>
        <Heading id={titleId} className="text-[28px] leading-tight font-semibold tracking-tight text-balance text-foreground sm:text-[34px]">
          {title}
        </Heading>
        {description && <p className="mt-4 text-[15px] leading-relaxed text-pretty text-muted-foreground">{description}</p>}
      </div>
      <Accordion variant="flush" multiple={multiple} defaultValue={defaultOpen} className={cn(!split && 'mt-10')}>
        {items.map((item) => (
          <AccordionItem key={item.id} value={item.id}>
            <AccordionTrigger headingLevel={Heading === 'h2' ? 3 : 4}>{item.question}</AccordionTrigger>
            <AccordionPanel>{item.answer}</AccordionPanel>
          </AccordionItem>
        ))}
      </Accordion>
    </section>
  );
}

import type { FaqItem } from './Faq';

/** Sample product-agnostic questions. */
export const sampleFaqs: FaqItem[] = [
  { id: 'trial', question: 'Is there a free trial?', answer: 'Yes. Every paid plan starts with a 14-day trial, no card required. You can cancel at any time during the trial.' },
  { id: 'billing', question: 'How is usage billed?', answer: 'Usage is metered per project and billed monthly. You can set a spending limit and get alerts before you reach it.' },
  { id: 'plans', question: 'Can I change plans later?', answer: 'Upgrade or downgrade whenever you like. Changes are prorated to the day on your next invoice.' },
  { id: 'members', question: 'Can I invite people outside my organization?', answer: 'Yes. Guests only get access to the projects you share with them.' },
  { id: 'data', question: 'Where is my data stored?', answer: 'You choose the region when you create a project. Data stays in that region unless you move it.' },
];
